-- Enable necessary extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Create profiles table
CREATE TABLE profiles (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id uuid REFERENCES auth.users ON DELETE CASCADE,
  full_name text NOT NULL,
  email text NOT NULL,
  phone text,
  course text,
  student_id text,
  profile_photo text,
  role text DEFAULT 'student' CHECK (role IN ('student', 'admin')),
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS on profiles
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for profiles
CREATE POLICY "Users can view their own profile" ON profiles
  FOR SELECT USING (user_id = auth.uid());

CREATE POLICY "Users can update their own profile" ON profiles
  FOR UPDATE USING (user_id = auth.uid());

CREATE POLICY "Users can insert their own profile" ON profiles
  FOR INSERT WITH CHECK (user_id = auth.uid());

-- Create announcements table
CREATE TABLE announcements (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  title text NOT NULL,
  content text NOT NULL,
  type text DEFAULT 'general' CHECK (type IN ('general', 'course', 'system', 'event')),
  created_by uuid REFERENCES auth.users ON DELETE CASCADE,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS on announcements
ALTER TABLE announcements ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for announcements
CREATE POLICY "Everyone can view announcements" ON announcements
  FOR SELECT TO authenticated USING (true);

CREATE POLICY "Only admins can create announcements" ON announcements
  FOR INSERT TO authenticated WITH CHECK (
    EXISTS (
      SELECT 1 FROM profiles 
      WHERE user_id = auth.uid() AND role = 'admin'
    )
  );

CREATE POLICY "Only admins can update announcements" ON announcements
  FOR UPDATE TO authenticated USING (
    EXISTS (
      SELECT 1 FROM profiles 
      WHERE user_id = auth.uid() AND role = 'admin'
    )
  );

CREATE POLICY "Only admins can delete announcements" ON announcements
  FOR DELETE TO authenticated USING (
    EXISTS (
      SELECT 1 FROM profiles 
      WHERE user_id = auth.uid() AND role = 'admin'
    )
  );

-- Create service_requests table
CREATE TABLE service_requests (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  title text NOT NULL,
  description text NOT NULL,
  type text NOT NULL,
  status text DEFAULT 'pending' CHECK (status IN ('pending', 'in-progress', 'completed', 'cancelled')),
  requested_by uuid REFERENCES auth.users ON DELETE CASCADE,
  assigned_to uuid REFERENCES auth.users ON DELETE SET NULL,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS on service_requests
ALTER TABLE service_requests ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for service_requests
CREATE POLICY "Users can view their own requests" ON service_requests
  FOR SELECT TO authenticated USING (requested_by = auth.uid());

CREATE POLICY "Admins can view all requests" ON service_requests
  FOR SELECT TO authenticated USING (
    EXISTS (
      SELECT 1 FROM profiles 
      WHERE user_id = auth.uid() AND role = 'admin'
    )
  );

CREATE POLICY "Users can create their own requests" ON service_requests
  FOR INSERT TO authenticated WITH CHECK (requested_by = auth.uid());

CREATE POLICY "Admins can update all requests" ON service_requests
  FOR UPDATE TO authenticated USING (
    EXISTS (
      SELECT 1 FROM profiles 
      WHERE user_id = auth.uid() AND role = 'admin'
    )
  );

-- Create messages table for chat
CREATE TABLE messages (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  content text NOT NULL,
  sender_id uuid REFERENCES auth.users ON DELETE CASCADE,
  receiver_id uuid REFERENCES auth.users ON DELETE CASCADE,
  service_request_id uuid REFERENCES service_requests ON DELETE CASCADE,
  is_read boolean DEFAULT false,
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS on messages
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for messages
CREATE POLICY "Users can view their own messages" ON messages
  FOR SELECT TO authenticated USING (
    sender_id = auth.uid() OR receiver_id = auth.uid()
  );

CREATE POLICY "Users can send messages" ON messages
  FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid());

CREATE POLICY "Users can update their received messages" ON messages
  FOR UPDATE TO authenticated USING (receiver_id = auth.uid());

-- Create indexes for better performance
CREATE INDEX idx_profiles_user_id ON profiles(user_id);
CREATE INDEX idx_profiles_role ON profiles(role);
CREATE INDEX idx_announcements_created_at ON announcements(created_at DESC);
CREATE INDEX idx_service_requests_requested_by ON service_requests(requested_by);
CREATE INDEX idx_service_requests_status ON service_requests(status);
CREATE INDEX idx_messages_sender_receiver ON messages(sender_id, receiver_id);
CREATE INDEX idx_messages_service_request ON messages(service_request_id);
CREATE INDEX idx_messages_created_at ON messages(created_at DESC);

-- Create function to broadcast announcements changes
CREATE OR REPLACE FUNCTION broadcast_announcements_changes()
RETURNS TRIGGER AS $$
SECURITY DEFINER
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM realtime.broadcast_changes(
    'announcements',
    TG_OP,
    TG_OP,
    TG_TABLE_NAME,
    TG_TABLE_SCHEMA,
    NEW,
    OLD
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- Create function to broadcast messages changes
CREATE OR REPLACE FUNCTION broadcast_messages_changes()
RETURNS TRIGGER AS $$
SECURITY DEFINER
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM realtime.broadcast_changes(
    'messages:' || COALESCE(NEW.service_request_id, OLD.service_request_id)::text,
    TG_OP,
    TG_OP,
    TG_TABLE_NAME,
    TG_TABLE_SCHEMA,
    NEW,
    OLD
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- Create function to broadcast service requests changes
CREATE OR REPLACE FUNCTION broadcast_service_requests_changes()
RETURNS TRIGGER AS $$
SECURITY DEFINER
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM realtime.broadcast_changes(
    'service_requests:' || COALESCE(NEW.id, OLD.id)::text,
    TG_OP,
    TG_OP,
    TG_TABLE_NAME,
    TG_TABLE_SCHEMA,
    NEW,
    OLD
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- Create triggers
CREATE TRIGGER announcements_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON announcements
  FOR EACH ROW EXECUTE FUNCTION broadcast_announcements_changes();

CREATE TRIGGER messages_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON messages
  FOR EACH ROW EXECUTE FUNCTION broadcast_messages_changes();

CREATE TRIGGER service_requests_broadcast_trigger
  AFTER INSERT OR UPDATE OR DELETE ON service_requests
  FOR EACH ROW EXECUTE FUNCTION broadcast_service_requests_changes();

-- Create RLS policies for realtime.messages table to allow private channels
CREATE POLICY "Users can read realtime messages for announcements" ON realtime.messages
  FOR SELECT TO authenticated USING (
    topic = 'announcements'
  );

CREATE POLICY "Users can read realtime messages for their service requests" ON realtime.messages
  FOR SELECT TO authenticated USING (
    topic LIKE 'service_requests:%' AND (
      -- User is the requester
      EXISTS (
        SELECT 1 FROM service_requests sr
        WHERE sr.id::text = SPLIT_PART(topic, ':', 2)
        AND sr.requested_by = auth.uid()
      )
      OR
      -- User is an admin
      EXISTS (
        SELECT 1 FROM profiles p
        WHERE p.user_id = auth.uid() AND p.role = 'admin'
      )
    )
  );

CREATE POLICY "Users can read realtime messages for their chats" ON realtime.messages
  FOR SELECT TO authenticated USING (
    topic LIKE 'messages:%' AND (
      -- User is involved in the service request
      EXISTS (
        SELECT 1 FROM service_requests sr
        WHERE sr.id::text = SPLIT_PART(topic, ':', 2)
        AND (sr.requested_by = auth.uid() OR EXISTS (
          SELECT 1 FROM profiles p
          WHERE p.user_id = auth.uid() AND p.role = 'admin'
        ))
      )
    )
  );

-- Allow users to write to realtime channels they can read
CREATE POLICY "Users can write realtime messages for announcements" ON realtime.messages
  FOR INSERT TO authenticated WITH CHECK (
    topic = 'announcements' AND EXISTS (
      SELECT 1 FROM profiles p
      WHERE p.user_id = auth.uid() AND p.role = 'admin'
    )
